package com.ecommerce.controller;
import com.ecommerce.dao.OrderDAO; import com.ecommerce.model.*; import com.ecommerce.util.View; import javax.servlet.*; import javax.servlet.annotation.WebServlet; import javax.servlet.http.*; import java.io.IOException; import java.util.*;
@WebServlet({"/checkout","/my-orders","/order-detail"}) public class OrderServlet extends HttpServlet{
 protected void doGet(HttpServletRequest req,HttpServletResponse resp)throws ServletException,IOException{try{User u=(User)req.getSession().getAttribute("user"); if(u==null){resp.sendRedirect(req.getContextPath()+"/login");return;} String p=req.getServletPath(); if("/my-orders".equals(p)){req.setAttribute("orders",new OrderDAO().findByUser(u.getId()));View.forward(req,resp,"my-orders.jsp");} else if("/order-detail".equals(p)){req.setAttribute("order",new OrderDAO().findById(Integer.parseInt(req.getParameter("id"))));View.forward(req,resp,"order-detail.jsp");} else {doPost(req,resp);} }catch(Exception e){throw new ServletException(e);}}
 protected void doPost(HttpServletRequest req,HttpServletResponse resp)throws ServletException,IOException{try{User u=(User)req.getSession().getAttribute("user"); if(u==null){resp.sendRedirect(req.getContextPath()+"/login");return;} List<CartItem> cart=(List<CartItem>)req.getSession().getAttribute("cart"); if(cart==null||cart.isEmpty()){resp.sendRedirect(req.getContextPath()+"/cart");return;} int id=new OrderDAO().createOrder(u,cart); req.getSession().removeAttribute("cart"); req.getSession().setAttribute("success","Siparişiniz başarıyla oluşturuldu. Sipariş No: "+id); resp.sendRedirect(req.getContextPath()+"/my-orders");}catch(Exception e){throw new ServletException(e);}}
}
